Timer = {}

-- Feature constants - used with get() and set() methods

--- Debug feature flag (10000)
Timer.FEATURE_DEBUG = 10000
--- Timer duration in milliseconds (settable)
Timer.FEATURE_TIME = 0
--- Timer operating mode: MODE_COUNT_DOWN or MODE_INTERVAL (settable)
Timer.FEATURE_MODE = 1
--- Current timer state: STATE_STOPPED, STATE_COUNTING, or STATE_PAUSED (read-only)
Timer.FEATURE_STATE = 2
--- Remaining time until OnTimer event fires in milliseconds (read-only)
Timer.FEATURE_VALUE = 3

-- Timer mode constants

--- Countdown mode - timer fires once after specified time
Timer.MODE_COUNT_DOWN = 0
--- Interval mode - timer fires repeatedly at specified intervals
Timer.MODE_INTERVAL = 1

-- Timer state constants

--- Timer is stopped
Timer.STATE_STOPPED = 0
--- Timer is actively counting
Timer.STATE_COUNTING = 1
--- Timer is paused
Timer.STATE_PAUSED = 2

-- Feature state constants (aliases for STATE_* constants)

--- Timer is stopped (feature state)
Timer.FEATURE_STATE_STOPPED = 0
--- Timer is counting (feature state)
Timer.FEATURE_STATE_COUNTING = 1
--- Timer is paused (feature state)
Timer.FEATURE_STATE_PAUSED = 2

-- Method constants - used with execute() method

--- Start/resume the timer
Timer.METHOD_START = 0
--- Stop the timer
Timer.METHOD_STOP = 1
--- Pause the timer
Timer.METHOD_PAUSE = 2

-- Event constants - used with add_event() method

--- Event fired when timer completes a countdown or interval
Timer.EVENT_ON_TIMER = 0
--- Event fired when timer starts
Timer.EVENT_ON_START = 1
--- Event fired when timer stops
Timer.EVENT_ON_STOP = 2
--- Event fired when timer pauses
Timer.EVENT_ON_PAUSE = 3


--- Create a new Timer instance
-- Initializes a timer object with the specified parameters. The timer starts in stopped state
-- with default values for time and mode.
--
-- @param id string|number Unique identifier for this timer instance (required)
-- @param address number Hardware address for the timer (optional, defaults to 0)
-- @param eventBus table Event bus instance for managing timer events (required)
-- @return table Timer instance with initialized properties
-- @usage
--   local timer = Timer:new("MyTimer", 1, eventBus)
--   timer:set(Timer.FEATURE_TIME, 5000)  -- 5 seconds
--   timer:set(Timer.FEATURE_MODE, Timer.MODE_INTERVAL)
--   timer:execute(Timer.METHOD_START)
function Timer:new(id, address, eventBus)

    if (id == nil) then
        error("Timer: missing id")
    end

    if (address == nil) then
        address = 0
    end

    if (eventBus == nil) then
        error("Timer: missing eventBus")
    end

    local timer = {
        id = id,
        description = "Timer",
        address = address,
        eventBus = eventBus,

        time = 0,
        mode = 0,
        state = 0,
        value = 0,
    }

    setmetatable(timer, self)
    self.__index = self

    return timer
end


--- Set a timer feature value
-- Sets configurable timer properties such as time duration and operating mode.
-- Only FEATURE_TIME and FEATURE_MODE can be set; other features are read-only.
--
-- @param key number Feature constant (FEATURE_TIME or FEATURE_MODE)
-- @param value number Value to set for the specified feature
-- @usage
--   timer:set(Timer.FEATURE_TIME, 10000)  -- Set timer to 10 seconds
--   timer:set(Timer.FEATURE_MODE, Timer.MODE_COUNT_DOWN)  -- Set to countdown mode
function Timer:set(key, value)

    if (value == nil) then
        error("Error: Timer:set(" .. key .. ", nil)")
    end

    if (self.debug == 1) then
        if (0 == key) then Logger.getShared():info("Timer:set(FEATURE_SET_TIME, ".. value ..")") end
        if (1 == key) then Logger.getShared():info("Timer:set(FEATURE_SET_MODE, ".. value ..")") end
    end


    if (Timer.FEATURE_TIME == key) then
        self.time = value
    end

    if (Timer.FEATURE_MODE == key) then
        self.mode = value
    end
end

--- Get a timer feature value
-- Retrieves current timer properties including time, mode, state, and remaining value.
-- All features can be read, though only FEATURE_TIME and FEATURE_MODE can be modified via set().
--
-- @param key number Feature constant (FEATURE_TIME, FEATURE_MODE, FEATURE_STATE, or FEATURE_VALUE)
-- @return number Current value of the requested feature
-- @usage
--   local timeRemaining = timer:get(Timer.FEATURE_VALUE)
--   local currentState = timer:get(Timer.FEATURE_STATE)
--   if currentState == Timer.STATE_COUNTING then
--       print("Timer is running, " .. timeRemaining .. "ms remaining")
--   end
function Timer:get(key)

    if (Timer.FEATURE_TIME == key) then
        -- Czas zliczen
        return self.time
    end

    if (Timer.FEATURE_MODE == key) then
        -- Tryb pracy: 0 - zliczanie w dol (CountDown), 1 - cykliczny (Interval)
        return self.mode
    end

    if (Timer.FEATURE_STATE == key) then
        -- Aktualny stan pracy timera: 0 - zatrzymany (stopped), 1 - liczy (counting), 2 - pauza (paused)
        return self.state
    end

    if (Timer.FEATURE_VALUE == key) then
        -- Czas jaki pozostal do wyzwolenia zdarzenia OnTimer
        return self:__getValue()
    end

end

--- Execute a timer method
-- Controls timer operation by executing start, stop, or pause commands.
-- This is the primary interface for controlling timer execution state.
--
-- @param key number Method constant (METHOD_START, METHOD_STOP, or METHOD_PAUSE)
-- @param value any Optional parameter (currently unused, reserved for future use)
-- @usage
--   timer:execute(Timer.METHOD_START)   -- Start/resume the timer
--   timer:execute(Timer.METHOD_PAUSE)   -- Pause the timer
--   timer:execute(Timer.METHOD_STOP)    -- Stop the timer completely
function Timer:execute(key, value)
    if (Timer.METHOD_START == key) then Logger.getShared():info("Timer:execute(METHOD_START)") end
    if (Timer.METHOD_STOP == key) then Logger.getShared():info("Timer:execute(METHOD_STOP)") end
    if (Timer.METHOD_PAUSE == key) then Logger.getShared():info("Timer:execute(METHOD_PAUSE)") end

    if (Timer.METHOD_START == key) then
        -- Uruchamia timer
        self:__start()
    end

    if (Timer.METHOD_STOP == key) then
        -- Zatrzymuje timer
        self:__stop()
    end

    if (Timer.METHOD_PAUSE == key) then
        -- Pauza timera
        self:__pause()
    end

end

--- Register an event callback
-- Attaches a callback function to be executed when the specified timer event occurs.
-- Events include timer completion, start, stop, and pause.
--
-- @param eventName number Event constant (EVENT_ON_TIMER, EVENT_ON_START, EVENT_ON_STOP, or EVENT_ON_PAUSE)
-- @param callback function Function to call when the event fires
-- @usage
--   timer:add_event(Timer.EVENT_ON_TIMER, function()
--       print("Timer fired!")
--   end)
--   timer:add_event(Timer.EVENT_ON_START, function()
--       print("Timer started")
--   end)
--- Convenience methods
function Timer:start()
    self:execute(Timer.METHOD_START)
end

function Timer:stop()
    self:execute(Timer.METHOD_STOP)
end

function Timer:pause()
    self:execute(Timer.METHOD_PAUSE)
end

function Timer:isRunning()
    return self:get(Timer.FEATURE_STATE) == Timer.STATE_COUNTING
end

function Timer:add_event(eventName, callback)
    self.eventBus:on(self, eventName, callback)
end

function Timer:__getState()
    return {
        id = self.id,
        address = self.address,
        type = 'Timer',
        time = self:get(Timer.FEATURE_TIME),
        mode = self:get(Timer.FEATURE_MODE),
        state = self:get(Timer.FEATURE_STATE),
        value = self:get(Timer.FEATURE_VALUE),
    }
end

-- ============================================
-- Internal timer management
-- ============================================

function Timer:__start()
    -- If already running, stop first
    if self.state == self.STATE_COUNTING then
        self:__clearTimers()
    end

    self.state = self.STATE_COUNTING
    self._startTime = os.time() * 1000  -- Track start time in ms
    self._remainingTime = self.time      -- Initialize remaining time

    self.eventBus:fire(self, self.EVENT_ON_START)

    if self.mode == self.MODE_INTERVAL then
        -- Interval mode: repeat every 'time' ms
        self._timerId = self.eventBus:setInterval(function()
            self._remainingTime = self.time  -- Reset for next interval
            self._startTime = os.time() * 1000
            self.eventBus:fire(self, Timer.EVENT_ON_TIMER)
        end, self.time)
    else
        -- CountDown mode: fire once after 'time' ms
        self._timerId = self.eventBus:setTimeout(function()
            self._remainingTime = 0
            self.state = self.STATE_STOPPED
            self.eventBus:fire(self, Timer.EVENT_ON_TIMER)
        end, self.time)
    end

    Logger:getShared():debug("[Timer] %s started: mode=%d, time=%dms", self.id, self.mode, self.time)
end

function Timer:__stop()
    if self.state == self.STATE_STOPPED then
        return
    end

    self:__clearTimers()
    self.state = self.STATE_STOPPED
    self._remainingTime = 0

    self.eventBus:fire(self, self.EVENT_ON_STOP)
    Logger:getShared():debug("[Timer] %s stopped", self.id)
end

function Timer:__pause()
    if self.state ~= self.STATE_COUNTING then
        return
    end

    -- Calculate remaining time
    local elapsed = (os.time() * 1000) - (self._startTime or 0)
    self._remainingTime = math.max(0, self.time - elapsed)

    self:__clearTimers()
    self.state = self.STATE_PAUSED

    self.eventBus:fire(self, self.EVENT_ON_PAUSE)
    Logger:getShared():debug("[Timer] %s paused, remaining=%dms", self.id, self._remainingTime)
end

function Timer:__resume()
    if self.state ~= self.STATE_PAUSED then
        return
    end

    self.state = self.STATE_COUNTING
    self._startTime = os.time() * 1000

    if self.mode == self.MODE_INTERVAL then
        -- Resume interval with remaining time, then switch to full interval
        self._timerId = self.eventBus:setTimeout(function()
            self._remainingTime = self.time
            self._startTime = os.time() * 1000
            self.eventBus:fire(self, Timer.EVENT_ON_TIMER)
            -- Start regular interval
            self._timerId = self.eventBus:setInterval(function()
                self._remainingTime = self.time
                self._startTime = os.time() * 1000
                self.eventBus:fire(self, Timer.EVENT_ON_TIMER)
            end, self.time)
        end, self._remainingTime)
    else
        -- CountDown mode: continue with remaining time
        self._timerId = self.eventBus:setTimeout(function()
            self._remainingTime = 0
            self.state = self.STATE_STOPPED
            self.eventBus:fire(self, Timer.EVENT_ON_TIMER)
        end, self._remainingTime)
    end

    Logger:getShared():debug("[Timer] %s resumed, remaining=%dms", self.id, self._remainingTime)
end

function Timer:__clearTimers()
    if self._timerId then
        self.eventBus:clearInterval(self._timerId)
        self._timerId = nil
    end
end

function Timer:__getValue()
    if self.state == self.STATE_STOPPED then
        return 0
    elseif self.state == self.STATE_PAUSED then
        return self._remainingTime or 0
    else
        -- Counting - calculate remaining
        local elapsed = (os.time() * 1000) - (self._startTime or 0)
        return math.max(0, self.time - elapsed)
    end
end

return Timer
